# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor fused_rnn_step(
    torch::Tensor x_t,
    torch::Tensor hidden,
    torch::Tensor weight,
    torch::Tensor bias
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_rnn_step", &fused_rnn_step,
          "Fused RNN step: tanh(W * [x_t; hidden]^T + b)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Fused RNN step kernel.
// Reads x_t and hidden_in as separate arrays (virtual concatenation over K),
// computes tanh(W[j,:] . [x_t; hidden] + b[j]) for each output neuron j,
// and writes the result to hidden_out -- no temporary combined tensor needed.
//
// Grid:  (batch_size,)
// Block: (hidden_size,)  -- one thread per output neuron
// Smem:  (input_size + hidden_size) * sizeof(float)  -- cached input row
__global__ void fused_rnn_step_kernel(
    const float* __restrict__ x_t,        // [batch_size, input_size]
    const float* __restrict__ hidden_in,   // [batch_size, hidden_size]
    const float* __restrict__ weight,      // [hidden_size, input_size + hidden_size]  (nn.Linear layout)
    const float* __restrict__ bias,        // [hidden_size]
    float* __restrict__ hidden_out,        // [batch_size, hidden_size]
    int batch_size,
    int input_size,
    int hidden_size
) {
    extern __shared__ float smem[];  // length = input_size + hidden_size

    int b   = blockIdx.x;
    int tid = threadIdx.x;
    int K   = input_size + hidden_size;

    // Cooperatively load x_t[b] into smem[0..input_size) and
    // hidden_in[b] into smem[input_size..K)
    const float* x_row = x_t      + (ptrdiff_t)b * input_size;
    const float* h_row = hidden_in + (ptrdiff_t)b * hidden_size;

    for (int k = tid; k < input_size;  k += blockDim.x) smem[k]= x_row[k];
    for (int k = tid; k < hidden_size; k += blockDim.x) smem[input_size + k] = h_row[k];
    __syncthreads();

    if (tid < hidden_size) {
        float acc = bias[tid];
        const float* w_row = weight + (ptrdiff_t)tid * K;

        // Manual unroll-4 over the K=1280 reduction
        int k = 0;
        for (; k + 7 < K; k += 8) {
            acc += w_row[k]     * smem[k];
            acc += w_row[k + 1] * smem[k + 1];
            acc += w_row[k + 2] * smem[k + 2];
            acc += w_row[k + 3] * smem[k + 3];
            acc += w_row[k + 4] * smem[k + 4];
            acc += w_row[k + 5] * smem[k + 5];
            acc += w_row[k + 6] * smem[k + 6];
            acc += w_row[k + 7] * smem[k + 7];
        }
        for (; k < K; ++k) {
            acc += w_row[k] * smem[k];
        }

        hidden_out[(ptrdiff_t)b * hidden_size + tid] = tanhf(acc);
    }
}

torch::Tensor fused_rnn_step(
    torch::Tensor x_t,
    torch::Tensor hidden,
    torch::Tensor weight,
    torch::Tensor bias
) {
    TORCH_CHECK(x_t.is_cuda() && hidden.is_cuda(), "fused_rnn_step: inputs must be CUDA tensors");
    TORCH_CHECK(x_t.scalar_type() == torch::kFloat32, "fused_rnn_step: only float32 supported");
    TORCH_CHECK(x_t.is_contiguous(),"fused_rnn_step: x_t must be contiguous");
    TORCH_CHECK(hidden.is_contiguous(),  "fused_rnn_step: hidden must be contiguous");
    TORCH_CHECK(weight.is_contiguous(),  "fused_rnn_step: weight must be contiguous");
    TORCH_CHECK(bias.is_contiguous(),    "fused_rnn_step: bias must be contiguous");

    int batch_size  = (int)x_t.size(0);
    int input_size  = (int)x_t.size(1);
    int hidden_size = (int)hidden.size(1);
    int K           = input_size + hidden_size;

    auto hidden_out = torch::empty({batch_size, hidden_size}, x_t.options());

    dim3 grid(batch_size);
    dim3 block(hidden_size);
    size_t smem_bytes = (size_t)K * sizeof(float);

    fused_rnn_step_kernel<<<grid, block, smem_bytes>>>(
        x_t.data_ptr<float>(),
        hidden.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        hidden_out.data_ptr<float>(),
        batch_size, input_size, hidden_size
    );

    return hidden_out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, input_size: int, hidden_size: int, output_size: int):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initialize the Vanilla RNN model.

                :param input_size: The number of input features (int).
                :param hidden_size: The size of the hidden state (int).
                :param output_size: The number of output features (int).
                """
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.output_size = output_size
        self.i2h = nn.Linear(input_size + hidden_size, hidden_size)
        self.h2o = nn.Linear(hidden_size, output_size)
        self.tanh = nn.Tanh()
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor, h0: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Forward pass of the Vanilla RNN.

                :param x: Input tensor of shape (seq_len, batch_size, input_size)
                :param h0: Initial hidden state tensor of shape (batch_size, hidden_size)
                :return: Output tensor of shape (seq_len, batch_size, output_size)
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        seq_len, batch_size, _ = x.size()
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        hidden = h0.to(x.device)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        hidden_states = x.new_empty((seq_len, batch_size, self.hidden_size))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        ext = _stark_get_extension()
        for t in range(seq_len):
            hidden = ext.fused_rnn_step(
            x[t].contiguous(),
            hidden.contiguous(),
            self.i2h.weight,
            self.i2h.bias
            )
            hidden_states[t] = hidden
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        flat_hidden = hidden_states.view(seq_len * batch_size, self.hidden_size)
        flat_out = flat_hidden.mm(self.h2o.weight.t()) + self.h2o.bias
        return flat_out.view(seq_len, batch_size, self.output_size)
        # <<<END_IMPROVE>>>

