            acc += w_row[k+1] * smem[k+1];
            acc += w_row[k+2] * smem[k+2];
            acc += w_row[k+3] * smem[k+3];
            acc += w_row[k+4] * smem[k+4];
            acc += w_row[k+5] * smem[k+5];
            acc += w_row[k+6] * smem[k+6];
            acc += w_row[k+7] * smem[k+7];
        }
        for (; k < K; ++k) acc += w_row[k] * smem[k];
        hidden_out[(ptrdiff_t)b * hidden_size + tid] = tanhf(acc);
    }
