torch::Tensor vanilla_rnn_hidden_forward(
    torch::Tensor x,          // [seq_len, batch_size, input_size]  contiguous
    torch::Tensor h0,         // [batch_size, hidden_size]           contiguous
    torch::Tensor i2h_weight, // [hidden_size, input_size+hidden_size]
    torch::Tensor i2h_bias,   // [hidden_size]
    torch::Tensor h2o_weight, // [output_size, hidden_size]
    torch::Tensor h2o_bias    // [output_size]
) {
    TORCH_CHECK(x.is_cuda() && h0.is_cuda(), "vanilla_rnn_hidden_forward: tensors must be CUDA");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "vanilla_rnn_hidden_forward: only float32");

    auto xc         = x.contiguous();
    auto hidden     = h0.contiguous();
    auto i2h_w      = i2h_weight.contiguous();
    auto i2h_b      = i2h_bias.contiguous();
    auto h2o_w      = h2o_weight.contiguous();
    auto h2o_b      = h2o_bias.contiguous();

    int seq_len    = (int)xc.size(0);
    int batch_size = (int)xc.size(1);
    int input_size = (int)xc.size(2);
    int hidden_size = (int)hidden.size(1);
    int output_size = (int)h2o_w.size(0);
    int K = input_size + hidden_size;

    // Preallocate hidden state buffer (ping-pong not needed, just two bufs)
    auto hidden_buf0 = hidden.clone();  // current hidden
    auto hidden_buf1 = torch::empty({batch_size, hidden_size}, xc.options());

    // Preallocate all hidden states for batched output projection
    auto all_hidden = torch::empty({seq_len, batch_size, hidden_size}, xc.options());

    dim3 grid(batch_size);
    dim3 block(hidden_size);
    size_t smem_bytes = (size_t)K * sizeof(float);

    float* cur_hidden = hidden_buf0.data_ptr<float>();
    float* nxt_hidden = hidden_buf1.data_ptr<float>();

    for (int t = 0; t < seq_len; ++t) {
        const float* x_t_ptr = xc.data_ptr<float>() + (ptrdiff_t)t * batch_size * input_size;

        fused_rnn_step_kernel<<<grid, block, smem_bytes>>>(
            x_t_ptr,
            cur_hidden,
            i2h_w.data_ptr<float>(),
            i2h_b.data_ptr<float>(),
            nxt_hidden,
            input_size,
            hidden_size
        );

        // Copy nxt_hidden into all_hidden[t]
        cudaMemcpyAsync(
            all_hidden.data_ptr<float>() + (ptrdiff_t)t * batch_size * hidden_size,
            nxt_hidden,
            (size_t)batch_size * hidden_size * sizeof(float),
            cudaMemcpyDeviceToDevice
        );

        // Swap buffers
        float* tmp = cur_hidden;
        cur_hidden = nxt_hidden;
        nxt_hidden = tmp;
    }

    // Batched output projection: [seq_len*batch_size, hidden_size] x [hidden_size, output_size]
    auto flat_hidden = all_hidden.view({seq_len * batch_size, hidden_size});
    auto flat_out = torch::addmm(h2o_b, flat_hidden, h2o_w.t());
    return flat_out.view({seq_len, batch_size, output_size});
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, input_size: int, hidden_size: int, output_size: int):
        super().__init__()
        # <<<IMPROVE:init_body>>>
